static const int fontIndexCount = sizeof(fontIndex) / sizeof(ChineseGlyphIdx);

/* ========== 实现 ========== */

int ChineseFont_FindGlyph(uint16_t unicode)
{
    int lo = 0, hi = fontIndexCount - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        uint16_t code = pgm_read_word(&fontIndex[mid].code);
        if (code == unicode) return pgm_read_word(&fontIndex[mid].glyphIdx);
        if (code < unicode) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

void ChineseFont_DrawChar(uint16_t unicode, int x, int y)
{
    int idx = ChineseFont_FindGlyph(unicode);
    if (idx >= 0) {
        display.drawBitmap(x, y, &glyphData[idx * 32], 16, 16, SSD1306_WHITE);
    } else {
        display.drawRect(x, y, 16, 16, SSD1306_WHITE);
    }
}

uint16_t ChineseFont_Utf8ToUnicode(const char* s, int* len)
{
    uint8_t c = s[0];
    if (c < 0x80) { *len = 1; return c; }
    if ((c & 0xE0) == 0xC0) { *len = 2; return ((c & 0x1F) << 6) | (s[1] & 0x3F); }
    if ((c & 0xF0) == 0xE0) { *len = 3; return ((c & 0x0F) << 12) | ((s[1] & 0x3F) << 6) | (s[2] & 0x3F); }
    *len = 1; return 0;
}

int ChineseFont_DrawString(const char* text, int x, int y)
{
    const char* s = text; int cx = x; int cnY = y - 4;
    while (*s) {
        int len; uint16_t uc = ChineseFont_Utf8ToUnicode(s, &len);
        if (len == 1 && uc < 0x80) { display.setCursor(cx, y); display.write((uint8_t)uc); cx += 6; }
        else if (len > 1) { ChineseFont_DrawChar(uc, cx, cnY); cx += 16; }
        s += len;
    }
    return cx;
}

int ChineseFont_GetStringWidth(const char* text)
{
    const char* s = text; int w = 0;
    while (*s) { int len; ChineseFont_Utf8ToUnicode(s, &len); w += (len == 1 && (uint8_t)*s < 0x80) ? 6 : 16; s += len; }
    return w;
}

int ChineseFont_Count(void) { return fontIndexCount; }
